syntax:
struct StructName {
    return_type (*function_pointer_name)(parameter_types);
};

// Usage:
struct StructName instance;
instance.function_pointer_name = function_implementation;
// Call:
instance.function_pointer_name(arguments);

code_example:
struct absInt {
    int (*operator)(int val);
};

int abs_value(int val) {
    return val < 0 ? -val : val;
}

int main() {
    struct absInt functor;
    functor.operator = abs_value;
    int result = functor.operator(-42);
    printf("Absolute value: %d\n", result);
    return 0;
}
